<?php
function nstPayrollDate($value){$d=DateTime::createFromFormat('!Y-m-d',(string)$value);return $d&&$d->format('Y-m-d')===$value;}
function nstPayrollDueDate($period,$day){if(!$day)return null;$start=DateTime::createFromFormat('!Y-m-d',$period.'-01');if(!$start||$start->format('Y-m')!==$period||$day<1||$day>31)return null;return $period.'-'.str_pad(min((int)$day,(int)$start->format('t')),2,'0',STR_PAD_LEFT);}
function nstPayrollCycle($period,$hire){
 if(!$hire||!nstPayrollDate($hire)||!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$period))return ['FechaPagoPeriodo'=>null,'FechaPrimerPago'=>null,'InicioCiclo'=>null,'FinCiclo'=>null];
 $day=(int)substr($hire,8,2);$hireMonth=new DateTime(substr($hire,0,7).'-01');$firstMonth=(clone $hireMonth)->modify('+1 month')->format('Y-m');$first=nstPayrollDueDate($firstMonth,$day);$due=nstPayrollDueDate($period,$day);if($due<$first)return ['FechaPagoPeriodo'=>null,'FechaPrimerPago'=>$first,'InicioCiclo'=>null,'FinCiclo'=>null];
 $previous=(new DateTime($period.'-01'))->modify('-1 month')->format('Y-m');$start=max($hire,nstPayrollDueDate($previous,$day));$end=(new DateTime($due))->modify('-1 day')->format('Y-m-d');return ['FechaPagoPeriodo'=>$due,'FechaPrimerPago'=>$first,'InicioCiclo'=>$start,'FinCiclo'=>$end];
}
function nstPayrollMoney($value){if(!is_numeric($value)||!is_finite((float)$value)||(float)$value<0||(float)$value>99999999)throw new InvalidArgumentException('Ingrese importes válidos, positivos y dentro del límite.');return round((float)$value,2);}
function nstPayrollTotals($x){
 $r=[];foreach(['Sueldo','Comision','Asignacion','OtrosIngresos','CTS','Gratificacion','BonoGratificacion','Vacaciones','OtrosDescuentos','RentaQuinta','BasePension','SeguroAFP','ComisionAFP','AporteEmpleador'] as $k)$r[$k]=nstPayrollMoney($x[$k]??0);
 $p=$x['Pension']??'NINGUNO';if(!in_array($p,['NINGUNO','ONP','AFP'],true))throw new InvalidArgumentException('Sistema de pensión inválido.');
 $r['Pension']=$p;$rate=$p==='ONP'?13:($p==='AFP'?10:0);$r['AportePension']=round($r['BasePension']*$rate/100,2);
 if($p!=='AFP'){$r['SeguroAFP']=0;$r['ComisionAFP']=0;}
 $r['Descuentos']=round($r['AportePension']+$r['SeguroAFP']+$r['ComisionAFP']+$r['OtrosDescuentos']+$r['RentaQuinta'],2);
 $r['Ingresos']=round($r['Sueldo']+$r['Comision']+$r['Asignacion']+$r['OtrosIngresos']+$r['CTS']+$r['Gratificacion']+$r['BonoGratificacion']+$r['Vacaciones'],2);
 $r['Neto']=round($r['Ingresos']-$r['Descuentos'],2);if($r['Neto']<0)throw new InvalidArgumentException('Los descuentos superan los ingresos.');
 $r['Regimen']=$x['Regimen']??'GENERAL';$r['AFP']=substr((string)($x['AFP']??''),0,40);$r['Observacion']=substr(trim((string)($x['Observacion']??'')),0,1000);$r['MotivoCambioSueldo']=substr(trim((string)($x['MotivoCambioSueldo']??'')),0,500);return $r;
}
function nstCommissionRows($db,$from,$to,$warehouse=0,$client=0){
 $sql="SELECT c.IdCliente,c.Cliente,c.DniRuc,v.idDocVenta,v.Serie,v.Numero,v.FechaDoc,v.IdAlmacen,v.valorComision,td.CodSunat,td.TipoDoc,SUM(d.Cantidad*d.Precio-IFNULL(d.Descuento,0)) TotalVenta,ROUND(GREATEST(0,SUM(d.Cantidad*d.Precio-IFNULL(d.Descuento,0)))*IFNULL(v.valorComision,0)/100,2) Generada FROM Ve_DocVenta v JOIN Ve_DocVentaDet d ON d.IdDocVenta=v.idDocVenta JOIN Ve_DocVentaCliente c ON c.IdCliente=v.IdComisionista JOIN Ve_DocVentaTipoDoc td ON td.IdTipoDoc=v.IdTipoDoc WHERE IFNULL(v.Anulado,0)=0 AND IFNULL(c.esComisionista,0)=1 AND v.valorComision>0 AND IFNULL(td.CodSunat,'') NOT IN ('07','08')";
 $args=[];if($client){$sql.=' AND c.IdCliente=?';$args[]=$client;}$sql.=' GROUP BY v.idDocVenta ORDER BY v.FechaDoc,v.idDocVenta';$s=$db->prepare($sql);$s->execute($args);$docs=$s->fetchAll(PDO::FETCH_ASSOC);
 // Existing legacy commission payments are distributed oldest first, across warehouses.
 $legacy=[];foreach($db->query("SELECT IdCliente,SUM(Importe) Total FROM Cb_CajaBanco WHERE IdTipoCajaBanco=7 AND IFNULL(Anulado,0)=0 AND Concepto LIKE 'Pago a comisionista %' GROUP BY IdCliente")->fetchAll(PDO::FETCH_ASSOC) as $x)$legacy[$x['IdCliente']]=max(0,round((float)$x['Total'],2));
 $allocated=[];foreach($db->query('SELECT a.IdDocVenta,SUM(a.Importe) Total FROM Rhu_ComisionAplicacion a JOIN Rhu_PlanillaPago p ON p.IdPago=a.IdPago JOIN Cb_CajaBanco cb ON cb.IdCajaBanco=p.IdCajaBanco WHERE p.Anulado=0 AND IFNULL(cb.Anulado,0)=0 GROUP BY a.IdDocVenta')->fetchAll(PDO::FETCH_ASSOC) as $x)$allocated[$x['IdDocVenta']]=(float)$x['Total'];
 $notes=$db->query("SELECT n.NroComprobanteModifica Referencia,ROUND(SUM(IF(t.CodSunat='07',-1,1)*(d.Cantidad*d.Precio-IFNULL(d.Descuento,0))),2) Ajuste FROM Ve_DocVenta n JOIN Ve_DocVentaTipoDoc t ON t.IdTipoDoc=n.IdTipoDoc JOIN Ve_DocVentaDet d ON d.IdDocVenta=n.idDocVenta WHERE IFNULL(n.Anulado,0)=0 AND t.CodSunat IN ('07','08') AND n.NroComprobanteModifica IS NOT NULL GROUP BY n.NroComprobanteModifica")->fetchAll(PDO::FETCH_KEY_PAIR);
 $rows=[];foreach($docs as $d){$ref=$d['Serie'].'-'.$d['Numero'];$d['Generada']=max(0,round((float)$d['Generada']+($notes[$ref]??0)*(float)$d['valorComision']/100,2));$id=$d['IdCliente'];$generated=(float)$d['Generada'];$old=min($generated,$legacy[$id]??0);$legacy[$id]=max(0,($legacy[$id]??0)-$old);$d['Pagada']=round($old+($allocated[$d['idDocVenta']]??0),2);$d['Pendiente']=max(0,round($generated-$d['Pagada'],2));if(substr($d['FechaDoc'],0,10)>=$from&&substr($d['FechaDoc'],0,10)<=$to&&(!$warehouse||(int)$d['IdAlmacen']===$warehouse))$rows[]=$d;}return $rows;
}
return function($app){
 $auth=function($request,$response,$action){if(session_status()!==PHP_SESSION_ACTIVE)session_start();$user=$_SESSION['user']??'';if(empty($_SESSION['payroll_csrf']))$_SESSION['payroll_csrf']=bin2hex(random_bytes(24));$csrf=$_SESSION['payroll_csrf'];session_write_close();if(strtoupper($request->getMethod())==='POST'&&!hash_equals($csrf,(string)$request->getParam('_csrf')))return $response->withJson(['error'=>'Actualice la página antes de guardar.'],403);if(!$user)return $response->withJson(['error'=>'Inicie sesión nuevamente.'],401);try{return $action($user);}catch(InvalidArgumentException $e){if($this->db->inTransaction())$this->db->rollBack();return $response->withJson(['error'=>$e->getMessage()],422);}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();error_log('[NST-PLANILLA] '.$e->getMessage());return $response->withJson(['error'=>'No se pudo completar la operación. Actualice e intente nuevamente.'],500);}};
 $app->get('/planilla/resumen',function($q,$r)use($auth){$run=$auth->bindTo($this);return $run($q,$r,function($user)use($q,$r){$db=$this->db;$period=$q->getParam('periodo')?:date('Y-m');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$period))throw new InvalidArgumentException('Periodo inválido.');$from=$q->getParam('desde')?:$period.'-01';$to=$q->getParam('hasta')?:date('Y-m-t',strtotime($period.'-01'));if(!nstPayrollDate($from)||!nstPayrollDate($to)||$from>$to)throw new InvalidArgumentException('Rango de fechas inválido.');
 $staff=$db->query("SELECT e.IdEmpleado,e.Empleado,e.DniRuc,e.Telefono,IFNULL(p.Cargo,'') Cargo,IFNULL(p.IdAlmacen,0) IdAlmacen,IFNULL(p.Sueldo,0) Sueldo,IFNULL(p.Regimen,'GENERAL') Regimen,IFNULL(p.Pension,'NINGUNO') Pension,IFNULL(p.AFP,'') AFP,IFNULL(p.TasaAFP,0) TasaAFP,p.FechaIngreso,p.DiaPago,IFNULL(p.Banco,'') Banco,IFNULL(p.NumeroCuenta,'') NumeroCuenta,IFNULL(p.CCI,'') CCI,IFNULL(p.Titular,'') Titular,IFNULL(p.Activo,1) Activo FROM Rhu_Empleado e LEFT JOIN Rhu_PlanillaPersonal p ON p.IdEmpleado=e.IdEmpleado WHERE IFNULL(e.Anulado,0)=0 ORDER BY e.Empleado")->fetchAll(PDO::FETCH_ASSOC);
 $s=$db->prepare('SELECT p.*,e.Empleado,e.DniRuc,IFNULL((SELECT SUM(pg.Importe) FROM Rhu_PlanillaPago pg JOIN Cb_CajaBanco cb ON cb.IdCajaBanco=pg.IdCajaBanco WHERE pg.IdPlanilla=p.IdPlanilla AND pg.Anulado=0 AND IFNULL(cb.Anulado,0)=0),0) Pagado FROM Rhu_PlanillaPeriodo p JOIN Rhu_Empleado e ON e.IdEmpleado=p.IdEmpleado WHERE p.Periodo=? ORDER BY e.Empleado');$s->execute([$period]);$liqs=$s->fetchAll(PDO::FETCH_ASSOC);foreach($staff as &$person){$person=array_merge($person,nstPayrollCycle($period,$person['FechaIngreso']));$person['DiaPago']=$person['FechaIngreso']?(int)substr($person['FechaIngreso'],8,2):null;}unset($person);foreach($liqs as &$x){$x['Detalle']=json_decode($x['Detalle'],true);$x['Saldo']=round($x['Neto']-$x['Pagado'],2);}unset($x);
 $s=$db->prepare("SELECT p.*,e.Empleado,c.Cliente,cu.Cuenta,pp.Periodo,cb.Anulado CajaAnulado,(SELECT GROUP_CONCAT(DISTINCT v.IdAlmacen) FROM Rhu_ComisionAplicacion ca JOIN Ve_DocVenta v ON v.idDocVenta=ca.IdDocVenta WHERE ca.IdPago=p.IdPago) Almacenes FROM Rhu_PlanillaPago p LEFT JOIN Rhu_PlanillaPeriodo pp ON pp.IdPlanilla=p.IdPlanilla LEFT JOIN Rhu_Empleado e ON e.IdEmpleado=pp.IdEmpleado LEFT JOIN Ve_DocVentaCliente c ON c.IdCliente=p.IdCliente JOIN Cb_Cuenta cu ON cu.IdCuenta=p.IdCuenta JOIN Cb_CajaBanco cb ON cb.IdCajaBanco=p.IdCajaBanco WHERE p.Fecha>=? AND p.Fecha<=? ORDER BY p.IdPago DESC");$s->execute([$from,$to]);return $r->withJson(['csrf'=>$_SESSION['payroll_csrf'],'personal'=>$staff,'planilla'=>$liqs,'pagos'=>$s->fetchAll(PDO::FETCH_ASSOC),'cuentas'=>$db->query('SELECT IdCuenta,Cuenta FROM Cb_Cuenta WHERE IFNULL(Anulado,0)=0')->fetchAll(PDO::FETCH_ASSOC),'almacenes'=>$db->query('SELECT IdAlmacen,Almacen FROM Lo_Almacen WHERE IFNULL(Anulado,0)=0')->fetchAll(PDO::FETCH_ASSOC)]);});});
 $app->post('/planilla/personal',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){$db=$this->db;$id=(int)$q->getParam('IdEmpleado');$name=trim((string)$q->getParam('Empleado'));$dni=trim((string)$q->getParam('DniRuc'));$salary=nstPayrollMoney($q->getParam('Sueldo')??0);if(!$name||strlen($name)>200||strlen($dni)>50)throw new InvalidArgumentException('Ingrese nombre y documento válidos.');$db->beginTransaction();if($id){$s=$db->prepare('SELECT IdEmpleado FROM Rhu_Empleado WHERE IdEmpleado=? FOR UPDATE');$s->execute([$id]);if(!$s->fetchColumn())throw new InvalidArgumentException('El personal no existe.');$s=$db->prepare('UPDATE Rhu_Empleado SET Empleado=?,DniRuc=?,Telefono=?,UsuarioMod=?,FechaMod=NOW() WHERE IdEmpleado=?');$s->execute([$name,$dni,substr((string)$q->getParam('Telefono'),0,100),$user,$id]);}else{$s=$db->prepare('INSERT INTO Rhu_Empleado(Empleado,DniRuc,Telefono,Anulado,UsuarioReg,FechaReg) VALUES(?,?,?,0,?,NOW())');$s->execute([$name,$dni,substr((string)$q->getParam('Telefono'),0,100),$user]);$id=(int)$db->lastInsertId();}
 $reg=$q->getParam('Regimen')?:'GENERAL';$pension=$q->getParam('Pension')?:'NINGUNO';if(!in_array($reg,['GENERAL','PEQUENA','MICRO'],true)||!in_array($pension,['NINGUNO','AFP','ONP'],true))throw new InvalidArgumentException('Régimen o pensión inválidos.');$date=$q->getParam('FechaIngreso')?:null;if($date&&!nstPayrollDate($date))throw new InvalidArgumentException('Fecha de ingreso inválida.');
 $day=$date?(int)substr($date,8,2):null;$bank=trim((string)$q->getParam('Banco'));$accountNumber=trim((string)$q->getParam('NumeroCuenta'));$cci=trim((string)$q->getParam('CCI'));$holder=trim((string)$q->getParam('Titular'));if(strlen($bank)>80||strlen($accountNumber)>80||strlen($holder)>150||($cci!==''&&!preg_match('/^[0-9]{20}$/',$cci)))throw new InvalidArgumentException('Revise la cuenta bancaria. El CCI debe tener 20 digitos.');
 $s=$db->prepare('INSERT INTO Rhu_PlanillaPersonal(IdEmpleado,Cargo,IdAlmacen,Sueldo,Regimen,Pension,AFP,TasaAFP,FechaIngreso,Activo,UsuarioReg,FechaMod) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE Cargo=VALUES(Cargo),IdAlmacen=VALUES(IdAlmacen),Sueldo=VALUES(Sueldo),Regimen=VALUES(Regimen),Pension=VALUES(Pension),AFP=VALUES(AFP),TasaAFP=VALUES(TasaAFP),FechaIngreso=VALUES(FechaIngreso),Activo=VALUES(Activo),FechaMod=NOW()');$s->execute([$id,substr((string)$q->getParam('Cargo'),0,100),(int)$q->getParam('IdAlmacen'),$salary,$reg,$pension,substr((string)$q->getParam('AFP'),0,40),nstPayrollMoney($q->getParam('TasaAFP')??0),$date,$q->getParam('Activo')===false?0:1,$user]);$s=$db->prepare('UPDATE Rhu_PlanillaPersonal SET DiaPago=?,Banco=?,NumeroCuenta=?,CCI=?,Titular=? WHERE IdEmpleado=?');$s->execute([$day,$bank,$accountNumber,$cci,$holder,$id]);$db->commit();return $r->withJson(['IdEmpleado'=>$id]);});});
 $app->post('/planilla/periodo',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){$db=$this->db;$id=(int)$q->getParam('IdEmpleado');$period=$q->getParam('Periodo');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',(string)$period))throw new InvalidArgumentException('Periodo inválido.');$x=nstPayrollTotals($q->getParam('Detalle')?:[]);$db->beginTransaction();$s=$db->prepare('SELECT IdEmpleado FROM Rhu_Empleado WHERE IdEmpleado=? AND IFNULL(Anulado,0)=0 FOR UPDATE');$s->execute([$id]);if(!$s->fetchColumn())throw new InvalidArgumentException('Seleccione personal activo.');$s=$db->prepare('SELECT Sueldo FROM Rhu_PlanillaPersonal WHERE IdEmpleado=?');$s->execute([$id]);$salary=(float)$s->fetchColumn();if(abs($salary-$x['Sueldo'])>0.001){if($q->getParam('PrepararAdelanto'))throw new InvalidArgumentException('Al preparar un adelanto debe conservarse el sueldo mensual completo. El importe del adelanto se ingresa en el pago.');if($x['MotivoCambioSueldo']==='')throw new InvalidArgumentException('El sueldo difiere del sueldo configurado. Indique un motivo para ajustar el sueldo del periodo.');} $s=$db->prepare('SELECT IdPlanilla FROM Rhu_PlanillaPeriodo WHERE IdEmpleado=? AND Periodo=? FOR UPDATE');$s->execute([$id,$period]);$old=$s->fetchColumn();if($old){$s=$db->prepare('SELECT COUNT(*) FROM Rhu_PlanillaPago WHERE IdPlanilla=?');$s->execute([$old]);if($s->fetchColumn())throw new InvalidArgumentException('La liquidación tiene pagos registrados. No puede modificarse.');$s=$db->prepare('UPDATE Rhu_PlanillaPeriodo SET Detalle=?,Neto=?,UsuarioReg=?,FechaReg=NOW() WHERE IdPlanilla=?');$s->execute([json_encode($x,JSON_UNESCAPED_UNICODE),$x['Neto'],$user,$old]);}else{$s=$db->prepare('INSERT INTO Rhu_PlanillaPeriodo(IdEmpleado,Periodo,Detalle,Neto,UsuarioReg,FechaReg) VALUES(?,?,?,?,?,NOW())');$s->execute([$id,$period,json_encode($x,JSON_UNESCAPED_UNICODE),$x['Neto'],$user]);}$db->commit();return $r->withJson(['ok'=>true]);});});
