 $app->get('/planilla/comisiones/detalle',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){$from=$q->getParam('desde');$to=$q->getParam('hasta');$client=(int)$q->getParam('IdCliente');if(!$client||!nstPayrollDate($from)||!nstPayrollDate($to)||$from>$to)throw new InvalidArgumentException('Seleccione cliente y fechas validas.');$docs=nstCommissionRows($this->db,$from,$to,(int)$q->getParam('idAlmacen'),$client);if(!$docs)return $r->withJson([]);$ids=array_column($docs,'idDocVenta');$marks=implode(',',array_fill(0,count($ids),'?'));$query="SELECT d.IdDocVenta,d.IdDocVentaDet,d.IdProducto,COALESCE(NULLIF(p.Producto,''),CONCAT('Producto ',d.IdProducto)) Producto,p.CodigoBarra,d.Cantidad,d.Precio,IFNULL(d.Descuento,0) Descuento,ROUND(d.Cantidad*d.Precio-IFNULL(d.Descuento,0),2) Total,d.Descripcion FROM Ve_DocVentaDet d LEFT JOIN Gen_Producto p ON p.IdProducto=d.IdProducto WHERE d.IdDocVenta IN ($marks) ORDER BY d.IdDocVenta,d.IdDocVentaDet";$stmt=$this->db->prepare($query);$stmt->execute($ids);$lines=[];foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $line)$lines[$line['IdDocVenta']][]=$line;foreach($docs as &$doc)$doc['Productos']=$lines[$doc['idDocVenta']]??[];unset($doc);return $r->withJson($docs);});});
 $app->get('/planilla/adelantos',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){$id=(int)$q->getParam('IdEmpleado');$period=(string)$q->getParam('Periodo');if(!$id||!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$period))throw new InvalidArgumentException('Seleccione personal y periodo.');$s=$this->db->prepare("SELECT pg.IdPago,pg.Fecha,pg.Importe,pg.Referencia,pg.UsuarioReg,pg.Anulado,pg.UsuarioAnula,cb.Anulado CajaAnulado,c.Cuenta,p.Periodo FROM Rhu_PlanillaPago pg JOIN Rhu_PlanillaPeriodo p ON p.IdPlanilla=pg.IdPlanilla JOIN Cb_Cuenta c ON c.IdCuenta=pg.IdCuenta JOIN Cb_CajaBanco cb ON cb.IdCajaBanco=pg.IdCajaBanco WHERE p.IdEmpleado=? AND p.Periodo=? AND pg.Tipo='ADELANTO' ORDER BY pg.Fecha DESC,pg.IdPago DESC");$s->execute([$id,$period]);return $r->withJson($s->fetchAll(PDO::FETCH_ASSOC));});});
 $app->post('/planilla/pago',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){$db=$this->db;$amount=nstPayrollMoney($q->getParam('Importe'));$account=(int)$q->getParam('IdCuenta');$date=$q->getParam('Fecha');$token=(string)$q->getParam('Token');$type=$q->getParam('Tipo');$pid=(int)$q->getParam('IdPlanilla');$client=(int)$q->getParam('IdCliente');if($amount<=0||!nstPayrollDate($date)||!preg_match('/^[a-zA-Z0-9-]{16,80}$/',$token)||(!in_array($type,['SUELDO','ADELANTO','COMISION','CTS','GRATIFICACION','VACACIONES','COMISION_CLIENTE'],true)))throw new InvalidArgumentException('Revise tipo, fecha, importe y solicitud de pago.');$db->beginTransaction();$s=$db->prepare('SELECT IdPago FROM Rhu_PlanillaPago WHERE Token=?');$s->execute([$token]);if($existing=$s->fetchColumn()){$db->commit();return $r->withJson(['IdPago'=>$existing,'repetido'=>true]);}$s=$db->prepare('SELECT IdCuenta FROM Cb_Cuenta WHERE IdCuenta=? AND IFNULL(Anulado,0)=0');$s->execute([$account]);if(!$s->fetchColumn())throw new InvalidArgumentException('Seleccione una cuenta activa.');$alloc=[];$destination=null;
